import { YoutubeVideo } from './content.model';
import snapshot from './youtube-videos.json';

/**
 * Generated by `scripts/youtube/sync-youtube.mjs` (run by hand), never edited by hand. Imported
 * rather than fetched so titles and posters are prerendered into `/videos`.
 */
export const YOUTUBE_VIDEOS: readonly YoutubeVideo[] = snapshot.videos;

export const VIDEOS_COUNT = YOUTUBE_VIDEOS.length;

export const youtubeClipSrc = (video: YoutubeVideo): string => `/videos/${video.id}.mp4`;
export const youtubePosterSrc = (video: YoutubeVideo): string => `/videos/${video.id}.jpg`;
export const youtubeWatchUrl = (video: YoutubeVideo): string =>
  `https://www.youtube.com/watch?v=${video.id}`;
